	res, path := [][]string{}, []string{}
	isPal := func(t string) bool {
		for i, j := 0, len(t)-1; i < j; i, j = i+1, j-1 {
			if t[i] != t[j] {
				return false
			}
		}
		return true
	}
	var dfs func(start int)
	dfs = func(start int) {
		if start == len(s) {
			res = append(res, append([]string(nil), path...))
			return
		}
		for end := start + 1; end <= len(s); end++ {
			piece := s[start:end]
			if isPal(piece) {     // 这一段是回文才切
				path = append(path, piece)
				dfs(end)
				path = path[:len(path)-1]
			}
		}
	}
	dfs(0)
	return res
