class Solution:
    def partition(self, s: str) -> List[List[str]]:
        if not s:
            return [[]]
        return [[s[:i]] + rest
                for i in range(1, len(s) + 1) if s[:i] == s[i - 1::-1]
                for rest in self.partition(s[i:])]

